        /// <param name="src">an SDL_IOStream to load image data from.</param>
        /// <returns>The created resource (never null); the caller owns it and is responsible for freeing it.</returns>
        /// <exception cref="SdlException">The SDL call failed; the message carries the <c>SDL_GetError</c>
        ///   text.</exception>
        public static SdlSurface* LoadAVIFIO(nint src)
        {
            SdlSurface* result = PInvoke.LoadAVIFIO(src);
            if (result == null)
            {
                throw SdlException.FromError("IMG_LoadAVIF_IO failed");
            }
            return result;
        }

