        ///   available; call IMG_GetAnimationDecoderStatus() or SDL_GetError()
        ///   for more information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This function decodes the next frame in the animation decoder, returning it
        ///     as an SDL_Surface. The returned surface should be freed with
        ///     SDL_FreeSurface() when no longer needed.
        ///   </para>
        ///   <para>
        ///     If the animation decoder has no more frames or an error occurred while
        ///     decoding the frame, this function returns false. In that case, please call
        ///     SDL_GetError() for more information. If SDL_GetError() returns an empty
        ///     string, that means there are no more available frames. If SDL_GetError()
        ///     returns a valid string, that means the decoding failed.
        ///   </para>
        /// </remarks>
        /// <since>
        ///   This function is available since SDL_image 3.4.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.CreateAnimationDecoder"/>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.CreateAnimationDecoderIO"/>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.CreateAnimationDecoderWithProperties"/>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.GetAnimationDecoderStatus"/>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.ResetAnimationDecoder"/>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.CloseAnimationDecoder"/>
        public static bool GetAnimationDecoderFrame(ImgAnimationDecoder decoder, SdlSurface** frame, out ulong duration)
        {
            duration = default;
            fixed (ulong* durationPtr = &duration)
            {
                return PInvoke.GetAnimationDecoderFrame(decoder, frame, durationPtr) != 0;
            }
        }

        /// <summary>
        ///   Get the decoder status indicating the current state of the decoder.
        /// </summary>
        /// <param name="decoder">the decoder to get the status of.</param>
        /// <returns>
        ///   the status of the underlying decoder, or
        ///   IMG_DECODER_STATUS_INVALID if the given decoder is invalid.
        /// </returns>
        /// <since>
        ///   This function is available since SDL_image 3.4.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.GetAnimationDecoderFrame"/>
        public static ImgAnimationDecoderStatus GetAnimationDecoderStatus(ImgAnimationDecoder decoder) =>
            PInvoke.GetAnimationDecoderStatus(decoder);

        /// <summary>
        ///   Reset an animation decoder.
        /// </summary>
        /// <param name="decoder">the decoder to reset.</param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     Calling this function resets the animation decoder, allowing it to start
        ///     from the beginning again. This is useful if you want to decode the frame
        ///     sequence again without creating a new decoder.
        ///   </para>
        /// </remarks>
        /// <since>
        ///   This function is available since SDL_image 3.4.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.CreateAnimationDecoder"/>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.CreateAnimationDecoderIO"/>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.CreateAnimationDecoderWithProperties"/>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.GetAnimationDecoderFrame"/>
        /// <seealso cref="Brutal.SdlApi.Image.SdlImage.PInvoke.CloseAnimationDecoder"/>
        public static bool ResetAnimationDecoder(ImgAnimationDecoder decoder) =>
            PInvoke.ResetAnimationDecoder(decoder) != 0;

        /// <summary>
        ///   Close an animation decoder, finishing any decoding.
        /// </summary>
        /// <param name="decoder">the decoder to close.</param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
